CREATE DATABASE IF NOT EXISTS nlp CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE nlp;
CREATE TABLE IF NOT EXISTS script_family (script_id CHAR(36) PRIMARY KEY, canonical_code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, family VARCHAR(200), writing_direction VARCHAR(16) NOT NULL DEFAULT 'unknown', decipherment_status VARCHAR(32) NOT NULL DEFAULT 'partial', created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS source_document (document_id CHAR(36) PRIMARY KEY, external_id VARCHAR(256), title LONGTEXT, uri LONGTEXT, media_type VARCHAR(128), checksum_sha256 CHAR(64), captured_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS inscription (inscription_id CHAR(36) PRIMARY KEY, document_id CHAR(36), script_id CHAR(36) NOT NULL, scholarly_id VARCHAR(256), language_code VARCHAR(64), transliteration LONGTEXT, translation LONGTEXT, confidence DECIMAL(6,5), uncertainty TEXT, provenance JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(document_id) REFERENCES source_document(document_id), FOREIGN KEY(script_id) REFERENCES script_family(script_id));
CREATE TABLE IF NOT EXISTS glyph_observation (glyph_id CHAR(36) PRIMARY KEY, inscription_id CHAR(36) NOT NULL, sequence_no INT NOT NULL, unicode_codepoint VARCHAR(32), glyph_label VARCHAR(128), bounding_box JSON, image_uri LONGTEXT, recognized_text TEXT, confidence DECIMAL(6,5), damaged BOOLEAN NOT NULL DEFAULT FALSE, alternate_readings JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE(inscription_id,sequence_no), FOREIGN KEY(inscription_id) REFERENCES inscription(inscription_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS reading (reading_id CHAR(36) PRIMARY KEY, inscription_id CHAR(36) NOT NULL, reading_text LONGTEXT NOT NULL, transliteration LONGTEXT, normalized_text LONGTEXT, confidence DECIMAL(6,5), reviewer VARCHAR(256), evidence JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(inscription_id) REFERENCES inscription(inscription_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS translation_candidate (candidate_id CHAR(36) PRIMARY KEY, reading_id CHAR(36) NOT NULL, target_language VARCHAR(32) NOT NULL, translation LONGTEXT NOT NULL, model_id CHAR(36), confidence DECIMAL(6,5), rank_no INT, evidence JSON, human_verified BOOLEAN NOT NULL DEFAULT FALSE, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(reading_id) REFERENCES reading(reading_id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS model_registry (model_id CHAR(36) PRIMARY KEY, model_name VARCHAR(256) NOT NULL UNIQUE, architecture VARCHAR(128), task VARCHAR(128), provider VARCHAR(256), license VARCHAR(256), metadata JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE IF NOT EXISTS model_version (model_version_id CHAR(36) PRIMARY KEY, model_id CHAR(36) NOT NULL, version VARCHAR(128) NOT NULL, artifact_uri LONGTEXT, checksum_sha256 CHAR(64), parameters BIGINT, framework VARCHAR(128), metrics JSON, created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE(model_id,version), FOREIGN KEY(model_id) REFERENCES model_registry(model_id));
CREATE TABLE IF NOT EXISTS inference_run (run_id CHAR(36) PRIMARY KEY, model_version_id CHAR(36), inscription_id CHAR(36), operation VARCHAR(64) NOT NULL, input_hash CHAR(64), output JSON, latency_ms DECIMAL(18,3), confidence DECIMAL(6,5), created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), FOREIGN KEY(model_version_id) REFERENCES model_version(model_version_id), FOREIGN KEY(inscription_id) REFERENCES inscription(inscription_id));
